<script lang="ts">
  import { indexGuideline, loadGuideline, markReady, readHash, writeHash, type Guideline, type HashState, type Rule } from '../../shared/data.js';
  let g = $state.raw<Guideline | null>(null);
  let viewState = $state.raw<HashState>(readHash());
  let rec = $state(1);
  let input = $state('');
  let selected = $state('');
  let error = $state('');
  const ix = $derived(g ? indexGuideline(g) : null);
  const question = $derived.by(() => { const s = viewState; return g && s.view === 'trace' ? g.questions.find(q => q.id === s.question) : null; });
  const key = $derived(viewState.view === 'rule' ? `${viewState.document}:${viewState.sentence}` : '');
  const sentence = $derived(ix?.sentence(key));
  const doc = $derived(viewState.view === 'rule' ? ix?.docs.get(viewState.document) : null);
  const visible = $derived.by(() => {
    if (!g) return [];
    if (viewState.view === 'trace') return question?.statements.map(s => ix?.rules.get(`${s.document}:${s.sentence}`)).filter((r): r is Rule => !!r) ?? [];
    if (viewState.view === 'rule') { const r = ix?.rules.get(key); return r ? [r] : []; }
    const s = viewState;
    if (s.view === 'explore') return g.rules.filter(r => r.original.toLowerCase().includes(s.query.toLowerCase()));
    return g.rules.filter(r => ix?.docs.get(r.document)?.rec === rec);
  });
  const results = $derived.by(() => { const route = viewState; return g && route.view === 'explore' ? g.documents.flatMap(d => d.sentences.filter(s => s.ace.toLowerCase().includes(route.query.toLowerCase())).map(s => ({d,s}))) : []; });
  const conditions = $derived([...new Set(visible.map(r => r.condition).filter((c): c is string => !!c))]);
  const reached = $derived(g?.rules.filter(r => r.condition === selected).length ?? 0);
  function go(s: HashState) { viewState = s; selected = ''; writeHash(s); }
  function rule(r: Rule) { go({view:'rule',document:r.document,sentence:r.sentence}); }
  $effect(() => {
    const hash = () => { viewState = readHash(); selected = ''; };
    addEventListener('hashchange', hash);
    void loadGuideline().then(data => g = data).catch(e => error = String(e));
    return () => removeEventListener('hashchange', hash);
  });
  $effect(() => { if (g || error) { void viewState; queueMicrotask(markReady); } });
</script>

<svelte:head><title>Guideline circuit | CNL / CKC</title></svelte:head>
<header><span class="brand">CNL / CKC</span><span>Clinical knowledge, connected</span><span class="prototype">Graph prototype</span></header>
<main>
  <nav aria-label="Graph views">
    <button class:current={viewState.view === 'overview'} onclick={() => go({view:'overview'})}>Guideline circuit</button>
    <button class:current={viewState.view === 'trace'} onclick={() => g && go({view:'trace',question:g.questions.find(q=>q.id==='starting-opioid-therapy')!.id})}>Trace an answer</button>
    <form onsubmit={e => {e.preventDefault(); go({view:'explore',query:input});}}><label for="search">Explore the KB</label><input id="search" bind:value={input} placeholder="Find a clinical phrase"/><button>Find</button></form>
  </nav>
  {#if error}<p role="alert">{error}</p>{:else if !g || !ix}<p>Loading the guideline…</p>{:else}
    <section class="intro"><div><p class="small">CDC 2022 opioid prescribing guideline</p><h1>{viewState.view === 'overview' ? 'Inside the recommendation.' : viewState.view === 'trace' ? 'Follow the answer’s wiring.' : viewState.view === 'rule' ? 'Inspect one rule.' : 'Find the connected rules.'}</h1><p>Conditions enter. Modal gates connect them to actions.<br/>This is a map of structure, not a test of whether a rule fires.</p></div><div class="total"><b>{g.rules.length}</b><span>clinical rule gates<br/>in {g.recommendations.length} recommendations</span></div></section>
    <p class="legend">Nodes = conditions, modal gates and actions. Wires = membership in a rule. An output marked NOT is a negated action.</p>
    {#if viewState.view === 'overview'}
      <div class="bank" aria-label="Recommendations">{#each g.recommendations as r}<button class:active={rec === r.number} onclick={() => { rec=r.number; selected=''; }}><span>Rec {r.number}</span><svg viewBox="0 0 90 28" aria-hidden="true"><path d="M0 8H25M0 20H25M62 14H90"/><path d="M25 3H42Q65 3 65 14Q65 25 42 25H25Z"/></svg><small>{g.rules.filter(x => x.document === r.id).length} gates</small></button>{/each}</div>
      <h2>Recommendation {rec} <span class="muted">/ select an input to follow shared wiring</span></h2>
    {:else if viewState.view === 'trace'}
      <label class="question">Choose an answer <select value={question?.id} onchange={e => go({view:'trace',question:e.currentTarget.value})}>{#each g.questions as q}<option value={q.id}>{q.question}</option>{/each}</select></label>
      {#if !question}<p>Question not found. Choose an answer above.</p>{:else}<h2>{question.question}</h2><p class="notice">{g.derivation}</p><p>{question.statements.length} statements, in answer order. Each source terminal opens its rule and passage.</p>{/if}
    {:else if viewState.view === 'explore'}<h2>Search: “{viewState.query}”</h2><p>{results.length} matching sentences; {visible.length} clinical rule gates.</p>
    {:else if !sentence}<p role="status">Sentence not found: {key}. Return to the guideline circuit.</p>
    {/if}
    {#if conditions.length > 0}<details class="inputs"><summary>Input bus / {conditions.length} exact condition phrases. Open to trace shared wiring.</summary><div>{#each conditions as c}<button aria-pressed={selected === c} class:chosen={selected===c} onclick={() => selected = selected===c ? '' : c}><span class="socket">{selected===c ? '●' : '○'}</span>{c}</button>{/each}</div>{#if selected}<p class="structural">STRUCTURE: {reached} rule{reached===1?'':'s'} mention this exact input. No patient facts were evaluated.</p>{/if}</details>{/if}
    {#if visible.length > 0}<div class="column-head"><span>Condition input</span><span>Modal gate</span><span>Action output</span></div><section class="circuit" aria-label="Rule wiring">
      {#each visible as r,i}<article class:lit={selected && r.condition === selected} class:dim={selected && r.condition !== selected}>
        <div class="condition"><small>{viewState.view === 'trace' ? `Statement ${i+1}` : `${r.document} / S${r.sentence}`}</small><p>{r.condition ?? 'No explicit condition in this rule'}</p>{#if r.condition?.includes(' and ')}<span class="conjunction">AND in condition wording</span>{/if}</div>
        <div class="gate-wrap" class:compound={r.condition?.includes(' and ')}><svg class="wire" viewBox="0 0 200 100" preserveAspectRatio="none" aria-hidden="true"><path d="M0 50H200"/></svg>{#if r.condition?.includes(' and ')}<b class="and" title="Conjunction in the condition wording">AND</b>{/if}<div class="gate" class:fact={r.mode==='fact'} class:may={r.mode==='may'||r.mode==='can'} class:must={r.mode==='must'}><strong>{r.mode}</strong><small>{r.subject}</small></div></div>
        <div class="outputs">{#each r.actions as a}<div class="action">{#if a.polarity==='negative'}<b class="not">NOT</b>{/if}<span>{a.verb} {a.object}{#each a.modifiers as m}{' '}{m.preposition} {m.value}{/each}</span></div>{/each}<button class="source" onclick={() => rule(r)}>Open sentence {r.sentence} / page {ix.docs.get(r.document)?.page}</button></div>
      </article>{/each}
    </section>{/if}
    {#if viewState.view === 'rule' && sentence && doc}<section class="source-panel"><h2>{doc.id}, sentence {sentence.n}</h2><p class="small">{visible.length ? 'Clinical parse above; controlled-language sentence below.' : 'Text reading only. This sentence has no clinical rule parse.'}</p><blockquote>{sentence.ace}</blockquote>{#if !visible.length}<p><b>Condition (text reading):</b> {sentence.condition ?? 'No explicit condition'}</p><p><b>Conclusion (text reading):</b> {sentence.modal}{sentence.negated?' / negated':''}: {sentence.conclusion}</p>{/if}<h3>Guideline passage</h3><p>{doc.source}</p><a href={`${g.pdf}#page=${doc.page}`} target="_blank" rel="noreferrer">Read guideline page {doc.page}</a><details><summary>Every sentence in this document</summary>{#each doc.sentences as s}<p><a href={`#rule=${doc.id}:${s.n}`}>Sentence {s.n}</a> {s.ace}</p>{/each}</details></section>{/if}
    {#if viewState.view === 'trace' && question}<section class="source-panel"><h2>Answer statements and sources</h2>{#each question.statements as s,i}{@const d=ix.docs.get(s.document)}<details><summary>{i+1}. {ix.sentence(`${s.document}:${s.sentence}`)?.ace}</summary><p><a href={`#rule=${s.document}:${s.sentence}`}>{s.document}, sentence {s.sentence}</a> / page {d?.page}</p><p>{d?.source}</p><a href={`${g.pdf}#page=${d?.page}`} target="_blank" rel="noreferrer">Read the guideline page</a></details>{/each}</section>{/if}
    {#if viewState.view === 'explore'}<section class="source-panel"><h2>Matching sentences</h2>{#each results as {d,s}}<details><summary>{d.id}, sentence {s.n}</summary><p>{s.ace}</p><a href={`#rule=${d.id}:${s.n}`}>Inspect this sentence</a><p>{d.source}</p><a href={`${g.pdf}#page=${d.page}`} target="_blank" rel="noreferrer">Read page {d.page}</a></details>{/each}{#if !results.length}<p>No sentence matches. Try another clinical phrase.</p>{/if}</section>{/if}
    <section class="interlocks"><details><summary>Scope interlocks / {g.exclusions.length} exclusion records</summary><p>The recommendations do not apply under these conditions. The absence of an exclusion does not establish that a patient is in scope.</p>{#each g.exclusions as e}<p>{e.ace} <a href={`#rule=${e.document}:${e.sentence}`}>{e.document}, sentence {e.sentence}</a></p>{/each}</details><details><summary>Disconnected by supersession / {g.supersessions.length} statements</summary>{#each g.supersessions as s}<p><s>{s.ace}</s></p><p>Superseded {String(s.date).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3')} / <a href={s.url}>{s.citation}</a>. <a href={`#rule=${s.document}:${s.sentence}`}>Open source statement</a></p>{/each}</details></section>
    <footer>Prototype structure view. {g.derivation}<br/>Source: Centers for Disease Control and Prevention. Free on the CDC website. CDC does not endorse this demonstration.</footer>
  {/if}
</main>

<style>
  header{display:flex;gap:28px;align-items:center;padding:18px 36px;border-bottom:1px solid var(--border);background:var(--surface-raised)}.brand{font-weight:800;font-size:18px}.prototype{margin-left:auto;color:var(--text-muted)}main{max-width:1360px;margin:auto;padding:24px 36px 40px}button,a,input,select,summary{outline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--focus-ring)}button{cursor:pointer;color:var(--text);background:var(--surface-raised);border:1px solid var(--border);padding:9px 13px}a{color:var(--action)}nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap}nav .current{background:var(--action);color:var(--action-text)}form{margin-left:auto;display:flex;gap:8px;align-items:center}input,select{min-width:0;border:1px solid var(--border);background:var(--surface-raised);color:var(--text);padding:9px}input{width:190px}.intro{display:flex;justify-content:space-between;gap:24px;padding:34px 0 20px}.intro p{margin:8px 0;color:var(--text-muted)}h1{font-size:42px;line-height:1.12;letter-spacing:-1.5px;margin:10px 0 18px}h2{font-size:22px}h3{font-size:16px}.small{font-size:14px}.total{display:flex;align-items:center;gap:15px}.total b{font-size:72px;font-weight:500;color:var(--action)}.total span{font-size:14px}.legend{border-left:4px solid var(--action);padding:9px 15px;background:var(--surface-raised);font-size:14px}.bank{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:7px;margin:26px 0}.bank button{padding:10px 5px;display:grid;gap:5px;place-items:center}.bank svg{width:100%;height:28px;fill:none;stroke:currentColor;stroke-width:1.6}.bank .active{color:var(--action);border:2px solid var(--action);background:var(--surface-sunken)}.muted{font-size:15px;font-weight:400;color:var(--text-muted)}.inputs{margin:20px 0 24px}.inputs>div{display:flex;flex-wrap:wrap;gap:8px}.inputs button{max-width:350px;text-align:left;display:flex;align-items:center;gap:10px;font-size:13px;padding:10px}.inputs .chosen{border:2px solid var(--action);color:var(--action)}.socket{font-size:22px}.structural{color:var(--action);font-weight:700}.column-head{display:grid;grid-template-columns:32% 27% 41%;padding:8px 18px;font-size:13px;color:var(--text-muted)}.column-head span:nth-child(2){text-align:center}.circuit{border:1px solid var(--border);background:var(--surface-raised)}article{display:grid;grid-template-columns:32% 27% 41%;align-items:stretch;padding:24px 18px;border-bottom:1px solid var(--border);min-height:166px}article:last-child{border:0}.condition{padding-right:12px;overflow-wrap:anywhere}.condition small{font-size:12px;color:var(--text-muted)}.condition p{margin:8px 0;font-size:15px}.conjunction{font-size:11px;border:1px solid var(--border);padding:2px 6px}.gate-wrap{position:relative;display:grid;place-items:center}.wire{position:absolute;inset:0;width:100%;height:100%;stroke:var(--text-muted);stroke-width:2;fill:none}.gate{position:relative;border:2px solid var(--text-muted);border-radius:0 55px 55px 0;background:var(--surface-sunken);width:150px;min-height:85px;padding:14px 22px 14px 14px;display:grid;place-content:center;text-align:center}.gate strong{font-size:21px}.gate small{font-size:12px}.gate.may{border-radius:50%}.gate.must{border:4px double var(--text-muted);border-radius:0}.outputs{padding-left:22px;display:flex;flex-direction:column;justify-content:center;gap:9px;min-width:0}.action{border:1px solid var(--border);background:var(--surface);padding:12px;display:flex;align-items:center;gap:9px;overflow-wrap:anywhere;font-size:16px}.not{font-size:12px;padding:7px;border:2px solid var(--warn);color:var(--warn);border-radius:50%}.source{border:0;padding:0;align-self:flex-start;background:none;color:var(--action);text-decoration:underline;font-size:12px;text-align:left}.lit{background:var(--surface-sunken);box-shadow:inset 5px 0 var(--action)}.lit .wire{stroke:var(--action);stroke-width:4}.dim{background:var(--surface-raised)}.question{display:grid;gap:8px;margin-top:24px;max-width:750px}.notice{padding:12px;border:1px solid var(--border)}.source-panel{margin:30px 0;max-width:80ch}.source-panel blockquote{border-left:4px solid var(--action);margin:0;padding:14px 20px;background:var(--surface-raised);font-size:19px}.source-panel details,.interlocks details{border-top:1px solid var(--border);padding:16px 0}summary{cursor:pointer}.interlocks{margin-top:35px;padding:10px 18px;border:1px solid var(--border);background:var(--surface-sunken)}.interlocks details:first-child{border:0}.interlocks p{max-width:80ch}.interlocks a{overflow-wrap:anywhere}footer{font-size:12px;color:var(--text-muted);margin-top:30px;max-width:100ch}
  @media(max-width:750px){header{padding:15px 18px;gap:12px;font-size:12px}header>span:nth-child(2){display:none}main{padding:18px}.intro{display:block;padding-top:24px}h1{font-size:34px}.total{gap:12px}.total b{font-size:46px}.total span{font-size:13px}form{margin:8px 0 0;width:100%;display:grid;grid-template-columns:1fr auto}form label{grid-column:1/-1}input{width:100%}.bank{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:18px 0}.bank button{padding:6px}.bank svg{height:22px}.bank small{font-size:11px}.column-head{display:none}article{grid-template-columns:1fr;padding:18px;gap:0}.condition{padding:0}.gate-wrap{height:126px}.wire{transform:rotate(90deg);width:126px;left:calc(50% - 63px)}.gate{width:155px;min-height:75px}.outputs{padding:0}.source{font-size:13px}.inputs button{max-width:100%;width:100%}.muted{display:block}h2{font-size:21px}select{width:100%}.action{font-size:16px}.interlocks{padding:5px 12px}.source-panel{overflow-wrap:anywhere}}
  .inputs summary{font-size:14px;color:var(--text-muted);padding:8px 0}.inputs>div{padding-top:12px}.and{position:absolute;left:6px;width:48px;min-height:40px;display:grid;place-items:center;border:2px solid var(--text-muted);border-radius:0 22px 22px 0;background:var(--surface-sunken);font-size:12px}.compound .gate{transform:translateX(24px)}.gate.fact{border-radius:0;border-style:double}.lit .and,.lit .gate{border-color:var(--action)}
  @media(max-width:750px){.compound{height:182px}.compound .gate{transform:translateY(25px)}.and{left:calc(50% - 24px);top:10px}}
  @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
